def has_deadlock(wait_for):
    # wait_for[p] = p가 대기 중인 프로세스 목록
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {p: WHITE for p in wait_for}

    def dfs(u):
        color[u] = GRAY  # 탐색 중
        for v in wait_for.get(u, []):
            if color[v] == GRAY:  # 역방향 간선 → 사이클
                return True
            if color[v] == WHITE and dfs(v):
                return True
        color[u] = BLACK  # 탐색 완료
        return False

    for p in wait_for:
        if color[p] == WHITE and dfs(p):
            return True
    return False
